function d_slurm_schedule(P,R){var jobs=(P.jobs||[]).slice().sort(function(a,b){return b.nodes-a.nodes;});var nodes=P.nodes||8,t=0,used=0,busy=[];jobs.forEach(function(j){busy=busy.filter(function(b){return b.end>t;});var free=nodes-busy.reduce(function(s,b){return s+b.nodes;},0);if(free>=j.nodes){busy.push({nodes:j.nodes,end:t+j.time});used+=j.nodes*j.time;}else{t++;busy.push({nodes:j.nodes,end:t+j.time});used+=j.nodes*j.time;}});var makespan=Math.max.apply(null,busy.map(function(b){return b.end;}));return{jobs:jobs.length,makespan:makespan,utilization:+Math.min(1,used/(nodes*makespan)).toFixed(3)};}

